// Представление графа списком смежности
class Graph:
    def __init__(self, vertices):
        self.V = vertices
        self.adj = [[] for _ in range(vertices)]

    def addEdge(self, u, v):
        self.adj[u].append(v)
        self.adj[v].append(u)  // для неориентированного графа

// Поиск в глубину (DFS)
function DFS(graph, v, visited):
    visited[v] = True
    print(v, end=' ')

    for neighbor in graph.adj[v]:
        if not visited[neighbor]:
            DFS(graph, neighbor, visited)

// Поиск в ширину (BFS)
function BFS(graph, start):
    visited = [False] * graph.V
    queue = []

    visited[start] = True
    queue.append(start)

    while queue:
        v = queue.pop(0)
        print(v, end=' ')

        for neighbor in graph.adj[v]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

DFS.algorithm:
// Рекурсивная реализация DFS
function DFS(graph, vertex, visited, discovery_time, finish_time, time):
    visited[vertex] = True
    time[0] += 1
    discovery_time[vertex] = time[0]

    for neighbor in graph.adj[vertex]:
        if not visited[neighbor]:
            DFS(graph, neighbor, visited, discovery_time, finish_time, time)

    time[0] += 1
    finish_time[vertex] = time[0]

// Итеративная реализация DFS
function DFS_iterative(graph, start):
    visited = [False] * graph.V
    stack = [start]

    while stack:
        vertex = stack.pop()

        if not visited[vertex]:
            visited[vertex] = True
            print(vertex, end=' ')

            // Добавляем соседей в обратном порядке для соответствия рекурсивной версии
            for neighbor in reversed(graph.adj[vertex]):
                if not visited[neighbor]:
                    stack.append(neighbor)

Dijkstra.algorithm:
function dijkstra(graph, source):
    V = graph.V
    dist = [float('inf')] * V
    dist[source] = 0
    visited = [False] * V

    // Приоритетная очередь (мин-куча)
    import heapq
    pq = [(0, source)]  // (расстояние, вершина)

    while pq:
        current_dist, u = heapq.heappop(pq)

        if visited[u]:
            continue

        visited[u] = True

        for v, weight in graph.adj[u]:
            if not visited[v]:
                new_dist = current_dist + weight
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heapq.heappush(pq, (new_dist, v))

    return dist
